/*
 * A187398  Numbers divisible by at least three of their digits, all different
 *          and >1.
 * https://oeis.org/A187398
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 3672, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Numbers divisible by at least three of their digits, all different and >1 */

seq_t a(idx_t n)
{
    /* The sequence is generated by scanning integers in ascending order
       and keeping those that have at least three distinct decimal digits
       greater than 1, and that are divisible by at least three of those
       digits.  The function searches until the nth such number is found.
    */
    idx_t  target   = n;
    idx_t  found    = 0;
    seq_t  candidate = 0;   /* will be incremented to 1 on first loop iteration */

    while (1) {
        ++candidate;                     /* examine next integer */

        /* Record which digits >1 appear in the number (distinct). */
        unsigned mask = 0;               /* bits 0..7 represent digits 2..9 */

        seq_t temp = candidate;
        while (temp) {                  /* extract digits */
            unsigned d = (unsigned)(temp % 10);
            if (d > 1) mask |= 1u << (d - 2);
            temp /= 10;
        }
        if (mask == 0) continue;        /* no digit >1 */

        /* Count distinct digits >1 */
        unsigned distinct = 0;
        unsigned tmask = mask;
        while (tmask) {
            distinct += tmask & 1;
            tmask >>= 1;
        }
        if (distinct < 3) continue;      /* need at least three distinct digits */

        /* Count how many of those digits divide the candidate */
        unsigned divisible = 0;
        for (unsigned d = 2; d <= 9; ++d) {
            if (mask & (1u << (d - 2))) {
                if ((candidate % (seq_t)d) == 0) divisible++;
            }
        }
        if (divisible < 3) continue;      /* need at least three such digits */

        /* A valid number has been found */
        ++found;
        if (found == target) return candidate;
    }
}
